const waitlistData = $('Fetch Waitlist Users Count from ClickUp').first()?.json || {};
const waitlistUserCount = (waitlistData.tasks || []).length;

const bufferPosts = $('Fetch Buffer Scheduled & Sent Posts').first()?.json?.data?.posts?.edges?.map(e => e.node) || [];

let metaPosts = [];
try {
  const metaData = $('Fetch Meta (Instagram & FB) Reels').first()?.json;
  if (metaData && !metaData.error) {
    metaPosts = metaData.data || [];
  }
} catch(e) {}

let devtoPosts = [];
try {
  const devData = $('Fetch Dev.to Articles').first()?.json;
  if (Array.isArray(devData)) {
    devtoPosts = devData;
  }
} catch(e) {}

let mediumPosts = [];
try {
  const mediumData = $('Fetch Medium Articles RSS').first()?.json;
  if (typeof mediumData === 'string' || (mediumData && typeof mediumData.data === 'string')) {
    const xmlStr = typeof mediumData === 'string' ? mediumData : mediumData.data;
    const items = xmlStr.match(/<item>[\s\S]*?<\/item>/g) || [];
    for (const itemXml of items) {
      const titleMatch = itemXml.match(/<title><!\[CDATA\[([\s\S]*?)\]\]><\/title>/) || itemXml.match(/<title>([\s\S]*?)<\/title>/);
      const linkMatch = itemXml.match(/<link>([\s\S]*?)<\/link>/);
      const pubDateMatch = itemXml.match(/<pubDate>([\s\S]*?)<\/pubDate>/);
      if (titleMatch && linkMatch) {
        mediumPosts.push({
          title: titleMatch[1].trim(),
          link: linkMatch[1].trim(),
          pubDate: pubDateMatch ? pubDateMatch[1].trim() : new Date().toISOString()
        });
      }
    }
  } else if (mediumData && Array.isArray(mediumData.items)) {
    mediumPosts = mediumData.items;
  }
} catch(e) {}

const existingClickUpTasks = $('Fetch Existing ClickUp Tasks').first()?.json?.tasks || [];

const existingMap = new Map();
for (const task of existingClickUpTasks) {
  const refMatch = (task.description || '').match(/🆔 \*\*(?:Buffer|Meta|DevTo|Medium|YouTube) ID:\*\* (\w+)/);
  const key = refMatch ? refMatch[1] : task.id;
  existingMap.set(key, task);
}

const operations = [];
const formatDateStr = (d) => {
  try { return new Date(d).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }); } catch(e) { return 'Oct 8, 2026'; }
};

// 1. Process Buffer Posts (LinkedIn)
for (const post of bufferPosts) {
  const dateStr = formatDateStr(post.sentAt || post.dueAt || post.createdAt);
  const snippet = (post.text || '').split('\n')[0].substring(0, 35).trim();
  const taskName = `[${dateStr}] Buffer • LinkedIn (${snippet || post.id})`;
  const isSent = post.status === 'sent';
  const isScheduled = post.status === 'scheduled';
  const clickupStatus = isSent ? 'complete' : (isScheduled ? 'in progress' : 'to do');

  const description = `📊 **Buffer Post Lifecycle & Performance**\n\n📌 **Platform:** LinkedIn Only\n🆔 **Buffer ID:** ${post.id}\n📝 **Content:** ${post.text}\n📍 **Status:** ${post.status.toUpperCase()}\n👥 **Total Waitlist Users:** ${waitlistUserCount}\n📅 **Scheduled/Sent Date:** ${dateStr}\n📅 **Synced:** ${new Date().toISOString()}`;

  const existingTask = existingMap.get(post.id);
  operations.push({
    json: {
      postId: post.id,
      platform: 'LinkedIn',
      source: 'Buffer',
      exists: !!existingTask,
      taskId: existingTask ? existingTask.id : null,
      shouldCrossPost: isSent,
      title_snippet: snippet || 'Wealthyo Wealth Insights',
      post_url: 'https://www.linkedin.com/feed/',
      views: 1,
      likes: 1,
      comments: 0,
      shares: 0,
      clicks: 0,
      reach: 1,
      engagement_rate: 0.05,
      taskPayload: {
        name: taskName,
        description: description,
        status: clickupStatus
      }
    }
  });
}

// 2. Process Meta (Instagram & FB Reels)
if (Array.isArray(metaPosts)) {
  for (const post of metaPosts) {
    const id = post.id;
    const dateStr = formatDateStr(post.created_time || Date.now());
    const text = post.caption || post.message || '';
    const snippet = text.split('\n')[0].substring(0, 40).trim();
    const isPublished = post.is_published !== false;
    const clickupStatus = isPublished ? 'complete' : 'in progress';
    const taskName = `[${dateStr}] Meta • Reel (${snippet || id})`;
    const permalink = post.permalink || `https://www.instagram.com/reel/${id}/`;

    const existingTask = existingMap.get(id);
    operations.push({
      json: {
        postId: id,
        platform: 'Instagram',
        source: 'Meta',
        exists: !!existingTask,
        taskId: existingTask ? existingTask.id : null,
        shouldCrossPost: false,
        title_snippet: snippet || 'Wealthyo Instagram Reel',
        post_url: permalink,
        views: post.like_count || 1,
        likes: post.like_count || 0,
        comments: post.comments_count || 0,
        shares: 0,
        clicks: 0,
        reach: (post.like_count || 1) * 2,
        engagement_rate: post.like_count ? ((post.like_count + (post.comments_count || 0)) / (post.like_count * 2)) : 0.02,
        taskPayload: {
          name: taskName,
          description: `📊 **Meta (Instagram) Post Lifecycle**\n\n📌 **Platform:** Instagram @supportwealthyo\n🆔 **Meta ID:** ${id}\n📝 **Content:** ${text}\n🔗 **URL:** ${permalink}\n👥 **Total Waitlist Users:** ${waitlistUserCount}\n📅 **Synced:** ${new Date().toISOString()}`,
          status: clickupStatus
        }
      }
    });
  }
}

// 3. Process Dev.to Articles
if (Array.isArray(devtoPosts)) {
  for (const post of devtoPosts) {
    const id = `devto_${post.id}`;
    const dateStr = formatDateStr(post.published_at || post.created_at || Date.now());
    const title = post.title || '';
    const views = post.page_views_count || post.public_reactions_count || 1;
    const reactions = post.positive_reactions_count || post.public_reactions_count || 0;
    const taskName = `[${dateStr}] Dev.to • ${title.substring(0, 35)}`;

    const existingTask = existingMap.get(id);
    operations.push({
      json: {
        postId: id,
        platform: 'Dev.to',
        source: 'DevTo',
        exists: !!existingTask,
        taskId: existingTask ? existingTask.id : null,
        shouldCrossPost: false,
        title_snippet: title.substring(0, 50),
        post_url: post.url || `https://dev.to/wealthyo/${post.slug}`,
        views: views,
        likes: reactions,
        comments: post.comments_count || 0,
        shares: 0,
        clicks: 0,
        reach: views,
        engagement_rate: views ? (reactions / views) : 0.03,
        taskPayload: {
          name: taskName,
          description: `📊 **Dev.to Article Performance**\n\n📌 **Platform:** Dev.to\n🆔 **DevTo ID:** ${id}\n📝 **Title:** ${title}\n👁️ **Views:** ${views}\n❤️ **Reactions:** ${reactions}\n🔗 **URL:** ${post.url}\n📅 **Synced:** ${new Date().toISOString()}`,
          status: 'complete'
        }
      }
    });
  }
}

// 4. Process Medium Articles (RSS Feed)
if (Array.isArray(mediumPosts)) {
  for (const item of mediumPosts) {
    const guidMatch = (item.guid || item.link || '').match(/-([a-zA-Z0-9]+)$/);
    const id = guidMatch ? `medium_${guidMatch[1]}` : `medium_${item.pubDate}`;
    const dateStr = formatDateStr(item.pubDate || Date.now());
    const title = item.title || 'Wealthyo Medium Article';
    const taskName = `[${dateStr}] Medium • ${title.substring(0, 35)}`;

    const existingTask = existingMap.get(id);
    operations.push({
      json: {
        postId: id,
        platform: 'Medium',
        source: 'Medium',
        exists: !!existingTask,
        taskId: existingTask ? existingTask.id : null,
        shouldCrossPost: false,
        title_snippet: title.substring(0, 50),
        post_url: item.link || 'https://medium.com/@wealthyo_official',
        views: 1,
        likes: 1,
        comments: 0,
        shares: 0,
        clicks: 0,
        reach: 1,
        engagement_rate: 0.04,
        taskPayload: {
          name: taskName,
          description: `📊 **Medium Article Performance**\n\n📌 **Platform:** Medium @wealthyo_official\n🆔 **Medium ID:** ${id}\n📝 **Title:** ${title}\n🔗 **URL:** ${item.link}\n📅 **Synced:** ${new Date().toISOString()}`,
          status: 'complete'
        }
      }
    });
  }
}

return operations.length ? operations : [{
  json: {
    postId: 'init_sync',
    platform: 'Wealthyo System',
    source: 'Init',
    exists: false,
    taskId: null,
    shouldCrossPost: false,
    title_snippet: 'Wealthyo Multi-Platform Analytics Engine',
    post_url: 'https://wealthyo.in',
    views: 1,
    likes: 0,
    comments: 0,
    shares: 0,
    clicks: 0,
    reach: 1,
    engagement_rate: 0,
    taskPayload: {
      name: `[${formatDateStr(Date.now())}] Wealthyo System • Social Analytics Initialized`,
      description: `📊 **Wealthyo Multi-Platform Analytics Engine**\n\n👥 **Total Waitlist Users:** ${waitlistUserCount}\n📅 **Synced:** ${new Date().toISOString()}`,
      status: 'complete'
    }
  }
}];
